-- Learning activities: every lesson, Speak session, crossword, conversation
-- and speech a learner finishes, one row each, append-only. The streak and XP
-- used to count reviews only, so a day of Speak and lessons did not count as
-- a day studied; the tables those activities write keep only the latest run,
-- so this log is what lets streak and XP be rebuilt from what happened.
--
-- Generated by drizzle-kit, then made idempotent by hand. Purely additive.

CREATE TABLE IF NOT EXISTS "learning_activities" (
	"id" text PRIMARY KEY NOT NULL,
	"user_id" text NOT NULL,
	"language_id" text NOT NULL,
	"kind" text NOT NULL,
	"ref_id" text NOT NULL,
	"occurred_at" timestamp with time zone NOT NULL,
	"local_date" date NOT NULL,
	"timezone" text NOT NULL,
	"score" integer,
	"total" integer,
	"duration_ms" integer,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
